mkdir -p "$TMPDIR/probe" && cat > "$TMPDIR/probe/re.mjs" <<'EOF'
const GIT_RE = /(^(git@|http(s)?:\/\/)([\w\.\-@]+)(\/|:))(([\~,\.\w,\-,\_,\/]+)(.git){0,1}((\/){0,1}))/

const urls = [
  "git@github.com:IonicaBizau/git-stats.git",
  "git@github.com:org/repo.git",
  // does new URL throw? and what does GIT_RE extract
  "git@github.com/org/repo.git",
  "git@github.com:org/repo.git#@evil.com/x",
  "git@github.com:org/repo.git?x=@evil.com",
  "git@github.com:org/repo.git@evil.com",
  "git@evil.com#github.com:org/repo",
  "https://github.com@evil.com/org/repo.git",
  "https://github.com:x@evil.com/org/repo",
  "git@github.com:org/repo.git:evil.com/y",
  "git@a.com@b.com:org/repo",
  "git@github.com:../../../../etc/passwd",
]

for (const u of urls) {
  let urlThrew = false, host = null
  try { const p = new URL(u); host = p.host } catch (e) { urlThrew = true }
  const m = u.match(GIT_RE)
  console.log(JSON.stringify(u))
  console.log("   new URL throws:", urlThrew, urlThrew ? "" : "-> real host: " + host)
  if (m) {
    console.log("   GIT_RE resource/host =", JSON.stringify(m[4]), " pathname =", JSON.stringify("/" + m[6]), " matchedTextLen=", m[0].length, "of", u.length)
    if (m[0].length !== u.length) console.log("   *** TRAILING DROPPED:", JSON.stringify(u.slice(m[0].length)))
  } else {
    console.log("   GIT_RE: no match")
  }
  console.log()
}
EOF
node -I "$TMPDIR/probe/re.mjs"

